/**
 * webchat-config.js — IBM Bob Assistant Web Chat Configuration
 *
 * This file is generated by scripts/get_webchat_embed.sh.
 * Do NOT edit manually — run the script to regenerate from live platform values.
 *
 * Architecture:
 *   - window.wxOConfiguration holds the parameters for the wxO web-chat loader
 *   - The loader script (wxoLoader.js) is fetched from the platform's hostURL
 *   - On load, wxoLoader.init() renders the chat widget into #wxo-chat-root
 *
 * References:
 *   - https://developer.watson-orchestrate.ibm.com/agents/build_agent#web-chat-configuration
 *   - https://www.ibm.com/docs/en/watsonx/watson-orchestrate/current?topic=overview-how-web-chat-works
 *   - https://www.ibm.com/docs/en/watsonx/watson-orchestrate/current?topic=overview-embedding-web-chat-your-page
 */

// ---------------------------------------------------------------------------
// 1. Platform configuration object
//    Values are injected by scripts/get_webchat_embed.sh via:
//      orchestrate channels webchat embed --agent-name ibm_bob_assistant --env live
// ---------------------------------------------------------------------------
window.wxOConfiguration = {
  /**
   * Unique ID for this web-chat integration (from the wxO platform).
   * Retrieved via: orchestrate channels webchat embed --agent-name ibm_bob_assistant --env live
   * Also visible in the wxO UI → agent → Embed tab.
   * NOT a secret — safe to include in client-side code.
   */
  orchestrationID: "e65910fa61ce9072d64902d03f3d4774_75c2cabb-2b02-4d65-8127-a9cc65d1ee46",

  /**
   * Base URL of the wxO platform for this region (eu-de).
   * The loader script (wxoLoader.js) is served from this portal URL.
   * Value is injected by get_webchat_embed.sh from the ADK CLI output.
   * Confirmed: curl -sI https://eu-de.watson-orchestrate.cloud.ibm.com/wxochat/wxoLoader.js?embed=true → HTTP 200
   * Do NOT change to api.eu-de.* — that endpoint returns HTTP 400 for the loader.
   */
  hostURL: "https://eu-de.watson-orchestrate.cloud.ibm.com",

  /**
   * ID of the DOM element where the chat widget will be rendered.
   * Must match the <div id="..."> in index.html.
   */
  rootElementID: "wxo-chat-root",

  /**
   * Whether to show the floating launcher button (chat bubble icon).
   * Set to false if you want to control opening programmatically.
   */
  showLauncher: true,

  /**
   * IBM Cloud Resource Name (CRN) for this wxO instance.
   * Retrieve from: IBM Cloud UI → Resource list → your wxO instance → CRN
   * Or: ibmcloud resource service-instance <instance-name> --id
   */
  crn: "crn:v1:bluemix:public:watsonx-orchestrate:eu-de:a/e65910fa61ce9072d64902d03f3d4774:75c2cabb-2b02-4d65-8127-a9cc65d1ee46::",

  /**
   * Instance URL — the API backend the widget uses for auth and chat requests.
   * Without this, the widget derives the backend from hostURL (portal URL) → Auth Error.
   * Format: https://api.<region>.watson-orchestrate.cloud.ibm.com/instances/<instanceId>
   * Value comes from ORCHESTRATE_URL in .env.
   */
  instanceUrl: "https://api.eu-de.watson-orchestrate.cloud.ibm.com/instances/75c2cabb-2b02-4d65-8127-a9cc65d1ee46",

  /**
   * Deployment platform. Always "ibmcloud" for IBM Cloud hosted instances.
   */
  deploymentPlatform: "ibmcloud",

  /**
   * Agent-specific configuration.
   */
  chatOptions: {
    /**
     * The unique ID of the ibm_bob_assistant agent on the platform.
     * Visible in: orchestrate agents list (ID column) or wxO UI.
     */
    agentId: "5c3c69c8-be40-44c8-9681-3e7f21c64072",

    /**
     * The environment ID (corresponds to "live" deployment).
     * Retrieved from the embed snippet generated by the ADK CLI.
     */
    agentEnvironmentId: "dba7f186-fe9b-4d42-9735-ba2601645aac"
  }
};

// ---------------------------------------------------------------------------
// 2. Load the wxO chat widget asynchronously
//    Uses setTimeout(..., 0) to avoid blocking the main thread during page load.
// ---------------------------------------------------------------------------
setTimeout(function () {
  /**
   * Dynamically create a <script> element to load the wxO chat loader.
   * The loader is hosted by IBM and auto-updated with latest features.
   * To pin a specific version append: ?version=X.Y.Z&embed=true
   */
  const script = document.createElement("script");
  script.src = `${window.wxOConfiguration.hostURL}/wxochat/wxoLoader.js?embed=true`;
  script.async = true;

  script.addEventListener("load", function () {
    /**
     * wxoLoader.init() reads window.wxOConfiguration and renders the widget.
     * Must be called AFTER the loader script has finished loading.
     */
    if (typeof wxoLoader !== "undefined" && typeof wxoLoader.init === "function") {
      wxoLoader.init();
      console.info("[IBM Bob Chat] wxO loader initialised successfully.");
    } else {
      console.error("[IBM Bob Chat] wxoLoader not available — check hostURL and network access.");
    }
  });

  script.addEventListener("error", function (e) {
    console.error("[IBM Bob Chat] Failed to load wxoLoader.js:", e);
    showChatLoadError();
  });

  document.head.appendChild(script);
}, 0);

// ---------------------------------------------------------------------------
// 3. Event helpers — called by the chat widget lifecycle
// ---------------------------------------------------------------------------

/**
 * Show an inline error message inside the chat root if the loader fails.
 * Keeps the page usable even when the chat cannot load.
 */
function showChatLoadError() {
  const root = document.getElementById(window.wxOConfiguration.rootElementID);
  if (!root) return;
  root.innerHTML = `
    <div style="
      padding: 16px;
      background: #fff3cd;
      border: 1px solid #ffc107;
      border-radius: 6px;
      font-family: 'IBM Plex Sans', sans-serif;
      font-size: 14px;
      color: #856404;
      max-width: 320px;
    ">
      <strong>⚠️ Chat unavailable</strong><br>
      Unable to load the IBM Bob Assistant chat widget.<br>
      Check your network connection or visit
      <a href="https://eu-de.watson-orchestrate.cloud.ibm.com" target="_blank" rel="noopener">
        eu-de.watson-orchestrate.cloud.ibm.com
      </a> directly.
    </div>`;
}

/**
 * Programmatically send a starter message to the chat widget.
 * Call this to pre-populate the conversation with a suggested query.
 *
 * @param {string} message - The message text to inject into the chat.
 *
 * Example usage from browser console:
 *   sendChatMessage("What is IBM Bob?");
 */
function sendChatMessage(message) {
  if (typeof wxoLoader !== "undefined" && typeof wxoLoader.sendMessage === "function") {
    wxoLoader.sendMessage(message);
  } else {
    console.warn("[IBM Bob Chat] wxoLoader.sendMessage not available yet.");
  }
}

/**
 * Open the chat window programmatically (e.g. triggered by a CTA button).
 */
function openChat() {
  if (typeof wxoLoader !== "undefined" && typeof wxoLoader.openWindow === "function") {
    wxoLoader.openWindow();
  }
}

/**
 * Close the chat window programmatically.
 */
function closeChat() {
  if (typeof wxoLoader !== "undefined" && typeof wxoLoader.closeWindow === "function") {
    wxoLoader.closeWindow();
  }
}

